#include <iostream>
#include <string>

int countOccurrences(const std::string& text, const std::string& pattern) {
    int count = 0;
    size_t pos = 0;
    while ((pos = text.find(pattern, pos)) != std::string::npos) {
        ++count;
        pos += pattern.length();
    }
    return count;
}

int main() {
    std::string text = "This is a test string. This string is a test.";
    std::string pattern = "string";
    std::cout << countOccurrences(text, pattern) << std::endl; // Output: 2
    return 0;
}
```

The `countOccurrences` function iterates through the `text` string, using `find` to locate instances of the `pattern`. Each successful find increments the `count`, and `pos` advances to avoid overlapping matches. It returns the final tally.

